SCHEMA_SQL = ("\nCREATE TABLE upload_attempts (\n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trequest_key VARCHAR(200) NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\treference JSONB NOT NULL, \n\ttitle VARCHAR(200) NOT NULL, \n\tfilename VARCHAR(200) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tterminal_at TIMESTAMP WITH TIME ZONE, \n\treason TEXT, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, owner_id, request_key), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0 AND status IN ('reserved','committed','abandoned')), \n\tCHECK ((status='reserved' AND terminal_at IS NULL) OR (status<>'reserved' AND terminal_at IS NOT NULL))\n)\n\n", 'CREATE INDEX ix_upload_attempts_tenant_id ON upload_attempts (tenant_id)', '\nCREATE TABLE lifecycle_objects (\n\tproduct_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\treference JSONB NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstate JSONB NOT NULL, \n\tmanual_hold BOOLEAN, \n\tretention_until TIMESTAMP WITH TIME ZONE, \n\tprotection_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id) REFERENCES products (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0 AND protection_revision > 0)\n)\n\n', 'CREATE INDEX ix_lifecycle_objects_tenant_id ON lifecycle_objects (tenant_id)', '\nCREATE TABLE lifecycle_candidates (\n\tproduct_id UUID NOT NULL, \n\tobject_id UUID NOT NULL, \n\tactor_id UUID NOT NULL, \n\tdocument JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, object_id) REFERENCES lifecycle_objects (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id)\n)\n\n', 'CREATE INDEX ix_lifecycle_candidates_tenant_id ON lifecycle_candidates (tenant_id)', '\nCREATE TABLE lifecycle_intents (\n\tproduct_id UUID NOT NULL, \n\tobject_id UUID NOT NULL, \n\tactor_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\tdocument JSONB NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, intent_digest), \n\tFOREIGN KEY(tenant_id, product_id, object_id) REFERENCES lifecycle_objects (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0)\n)\n\n', 'CREATE INDEX ix_lifecycle_intents_tenant_id ON lifecycle_intents (tenant_id)', '\nCREATE TABLE lifecycle_requests (\n\tproduct_id UUID NOT NULL, \n\tobject_id UUID NOT NULL, \n\tactor_id UUID NOT NULL, \n\tkey VARCHAR(200) NOT NULL, \n\tfingerprint VARCHAR(64) NOT NULL, \n\tintent_id UUID NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, actor_id, key), \n\tFOREIGN KEY(tenant_id, product_id, object_id) REFERENCES lifecycle_objects (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, intent_id) REFERENCES lifecycle_intents (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id)\n)\n\n', 'CREATE INDEX ix_lifecycle_requests_tenant_id ON lifecycle_requests (tenant_id)')
